-- Exact application state plus one complete recognized platform family; unknown/mixed states STOP.
-- Reference snapshots and generator are maintained outside this repository.
-- Atomic DO; establish overall statement timeout in the runner before execution.
DO $fresh_permissions$
DECLARE s jsonb; actual jsonb; api jsonb; matched_family text;
 platform_expected jsonb; platform_expected_hashes jsonb;
 shared_expected jsonb := '{"functions":"83e8bbfe7bb56a491605f4ef6fdc3704ac9957acfa4e8b61e2cd5f5f6719a82b","relations":"42ecc32f63040863f65d42adcb33085085fffa199fd18fc36535cc3caf4cd4eb","policies":"2518dead117cb467ceb3ff45d3639cc5603784564e266175d3a432b2feeb3094","triggers":"1a3129b0dfc62b77de0596a7ba226838899312b2a0521598b392793b7bf88606","constraints":"15c744166874aa13cd381fbfb8237ce7603556a4b5b3915e835788a2cab3da9e","roles":"d3fe8314f6d0d1feb4edb7f0e520843dc470793613328cd3578db60cb4cdcf00","default_acls":"620807042ed5728c049688d35bca215935c489153a4d6a898caeed3f21551f44","role_memberships":"a4f0de5be400c639396dab0b4455673dbbb7d07a5cdbcb04d27669d2b159efdc","indexes":"03c34d542ce62ab445444d209da4dfb3a5a3c01d7198493c3e394b26e94711d8","auth_helpers":"95fcc78418975e0a544347cc19b8fb8e2fc245fa1c1b59be2a9d94b90bf90c4c","columns":"1bacc3112e3cb0cdc8cbd1258ee1e584af39a671424ca142d2655cb2477448f0","fresh_roles":"71d577c7ebf4848a88570a465c4de4e4b395b95a75a23f34da6f4e3097ffb50c","fresh_extensions":"3bef7f9f340160a2635a0817fec76b266c55cec7ca5b0aed817336d0d195fed8","fresh_column_acls":"4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11ba873c2f11161202b945"}'::jsonb;
 normalized_expected jsonb := '{"functions":"8b8f3190d930daa6e6689d382c624bc1eb3cc4c17e3e359b07700499f772bb37","relations":"2adbea28830fbf65d17e83ff37db3f4dfee51eda8655f177e484b4beb95c1273","policies":"2518dead117cb467ceb3ff45d3639cc5603784564e266175d3a432b2feeb3094","triggers":"1a3129b0dfc62b77de0596a7ba226838899312b2a0521598b392793b7bf88606","constraints":"15c744166874aa13cd381fbfb8237ce7603556a4b5b3915e835788a2cab3da9e","roles":"d3fe8314f6d0d1feb4edb7f0e520843dc470793613328cd3578db60cb4cdcf00","default_acls":"4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11ba873c2f11161202b945","role_memberships":"a4f0de5be400c639396dab0b4455673dbbb7d07a5cdbcb04d27669d2b159efdc","indexes":"03c34d542ce62ab445444d209da4dfb3a5a3c01d7198493c3e394b26e94711d8","auth_helpers":"95fcc78418975e0a544347cc19b8fb8e2fc245fa1c1b59be2a9d94b90bf90c4c","columns":"1bacc3112e3cb0cdc8cbd1258ee1e584af39a671424ca142d2655cb2477448f0","fresh_roles":"71d577c7ebf4848a88570a465c4de4e4b395b95a75a23f34da6f4e3097ffb50c","fresh_extensions":"3bef7f9f340160a2635a0817fec76b266c55cec7ca5b0aed817336d0d195fed8","fresh_column_acls":"4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11ba873c2f11161202b945"}'::jsonb;
 platform_old jsonb := '{"fresh_schemas":"006704c39483237d74e3b74fc231d1a3472e0d17a750a2a98088c4b95f240811","fresh_default_acls":"be69c14a1fc95141e3297bfd7ce54e9afbea7d993c66825dd95ae7aa3587eb4c","fresh_event_triggers":"1a9b7ab0b8701614e3eb8b03aa163637a7a47be17c2b7ea3f635772ca93a22dd","fresh_automatic_grant_functions":"91807175516ff6e89c085412b86e2660b798528c0864cdb966dca7e1bb507523"}'::jsonb;
 platform_new jsonb := '{"fresh_schemas":"b5ce77ff76916a9d746e403f5ab35c04cecdd638f2b4e01a17702a7b203d2d10","fresh_default_acls":"21ed1f8eb58498efd9683691d52747ca80c1eaecde4283806a031552e0d8a5cf","fresh_event_triggers":"2c02eab1912a93f00e2aea09c14660baebdb0dbb2f39e095330360fea6bf1087","fresh_automatic_grant_functions":"768dda577eac4c285d9d0f8cfad0f85bd80ce1d96d65065342ab2f393a554f42"}'::jsonb;
BEGIN
SET LOCAL search_path=pg_catalog,public;
SET LOCAL lock_timeout='3s';
LOCK TABLE public."coverage_events",public."direct_shift_offers",public."pilot_audit_aggregates",public."pilot_audit_events",public."pilot_invitations",public."profiles",public."shift_interests",public."shifts",public."workplace_members",public."workplace_observers",public."workplace_participant_codes",public."workplace_pilot_settings",public."workplace_shift_codes",public."workplaces" IN ACCESS EXCLUSIVE MODE;
IF current_setting('server_version_num')::integer / 10000 <> 17 OR current_user <> 'postgres' THEN RAISE EXCEPTION 'STOP: PG17 postgres runner required'; END IF;
IF EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND a.attnum>0 AND NOT a.attisdropped AND coalesce(array_length(a.attacl,1),0)>0) THEN RAISE EXCEPTION 'STOP: shared category public column ACL'; END IF;
IF EXISTS(SELECT 1 FROM pg_auth_members a JOIN pg_roles r ON r.oid=a.member WHERE r.rolname IN ('anon','authenticated','service_role')) THEN RAISE EXCEPTION 'STOP: shared category API role memberships'; END IF;
IF EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname IN ('anon','authenticated','service_role') AND (NOT has_schema_privilege(r.oid,'public','USAGE') OR has_schema_privilege(r.oid,'public','CREATE'))) THEN RAISE EXCEPTION 'STOP: shared category public schema API access'; END IF;
s:=jsonb_build_object('functions',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT p.proname AS name,pg_get_function_identity_arguments(p.oid) AS args,md5(pg_get_functiondef(p.oid)) AS definition_md5,pg_get_userbyid(p.proowner) AS owner,p.prosecdef AS definer,ARRAY(SELECT a::text FROM unnest(coalesce(p.proacl,acldefault('f',p.proowner))) a ORDER BY a::text COLLATE "C")::text AS acl FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind IN ('f','p') ORDER BY 1,2) q),'relations',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT c.relname AS name,c.relkind AS kind,pg_get_userbyid(c.relowner) AS owner,c.relrowsecurity AS rls,c.relforcerowsecurity AS force_rls,c.reloptions,ARRAY(SELECT a::text FROM unnest(coalesce(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 's'::"char" ELSE 'r'::"char" END,c.relowner))) a ORDER BY a::text COLLATE "C")::text AS acl,CASE WHEN c.relkind IN ('v','m') THEN md5(pg_get_viewdef(c.oid,true)) ELSE NULL END AS view_md5 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','f','S') ORDER BY 1) q),'policies',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT * FROM pg_policies WHERE schemaname='public' ORDER BY tablename,policyname) q),'triggers',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT c.relname AS relation,t.tgname AS name,t.tgenabled AS enabled,pg_get_triggerdef(t.oid) AS definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal ORDER BY 1,2) q),'constraints',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT c.relname AS relation,con.conname AS name,con.contype AS kind,con.convalidated AS validated,pg_get_constraintdef(con.oid) AS definition FROM pg_constraint con JOIN pg_class c ON c.oid=con.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' ORDER BY 1,2) q),'roles',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT rolname,rolsuper,rolbypassrls,rolinherit FROM pg_roles WHERE rolname IN ('postgres','supabase_admin','supabase_auth_admin','anon','authenticated','service_role','authenticator') ORDER BY rolname) q),'default_acls',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT pg_get_userbyid(d.defaclrole) AS owner,coalesce(n.nspname,'(global)') AS schema,d.defaclobjtype AS kind,ARRAY(SELECT a::text FROM unnest(d.defaclacl) a ORDER BY a::text COLLATE "C")::text AS acl FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE d.defaclrole='postgres'::regrole AND (d.defaclnamespace=0 OR n.nspname='public')) q),'role_memberships',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT g.rolname AS granted,m.rolname AS member,pg_get_userbyid(a.grantor) AS grantor,a.admin_option,to_jsonb(a)->'inherit_option' AS inherit_option,to_jsonb(a)->'set_option' AS set_option FROM pg_auth_members a JOIN pg_roles g ON g.oid=a.roleid JOIN pg_roles m ON m.oid=a.member) x),'indexes',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT c.relname AS relation,i.relname AS name,ix.indisunique,ix.indisvalid,ix.indisready,pg_get_indexdef(ix.indexrelid) AS definition FROM pg_index ix JOIN pg_class c ON c.oid=ix.indrelid JOIN pg_class i ON i.oid=ix.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' ORDER BY 1,2) q),'auth_helpers',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT p.proname AS name,pg_get_function_identity_arguments(p.oid) AS args,pg_get_userbyid(p.proowner) AS owner,p.proconfig AS config,md5(pg_get_functiondef(p.oid)) AS definition_md5 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='auth' AND p.proname IN ('uid','jwt','role') AND p.prokind='f') x),'columns',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT c.relname AS relation,a.attname AS name,a.attnum AS number,format_type(a.atttypid,a.atttypmod) AS type,a.attnotnull AS not_null,a.attidentity AS identity,a.attgenerated AS generated,pg_get_expr(d.adbin,d.adrelid) AS default_expression,a.attacl::text AS acl FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname='public' AND a.attnum>0 AND NOT a.attisdropped AND c.relkind IN ('r','p','v','m','f')) q),'fresh_roles',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolbypassrls FROM pg_roles ORDER BY rolname) q),'fresh_schemas',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT n.nspname AS name,pg_get_userbyid(n.nspowner) AS owner,ARRAY(SELECT a::text FROM unnest(coalesce(n.nspacl,acldefault('n',n.nspowner))) a ORDER BY a::text COLLATE "C")::text AS resolved_direct_acl FROM pg_namespace n WHERE n.nspname NOT LIKE 'pg_temp%' AND n.nspname NOT LIKE 'pg_toast%' ORDER BY 2) q),'fresh_default_acls',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT pg_get_userbyid(d.defaclrole) AS owner,CASE WHEN d.defaclnamespace=0 THEN '<global>' ELSE n.nspname END AS schema,d.defaclobjtype AS kind,ARRAY(SELECT a::text FROM unnest(d.defaclacl) a ORDER BY a::text COLLATE "C")::text AS acl FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace ORDER BY 1,2,3) q),'fresh_event_triggers',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT e.evtname AS name,e.evtevent AS event,pg_get_userbyid(e.evtowner) AS owner,e.evtenabled AS enabled,e.evttags AS tags,n.nspname AS function_schema,p.proname AS function_name,md5(pg_get_functiondef(p.oid)) AS function_definition_md5 FROM pg_event_trigger e JOIN pg_proc p ON p.oid=e.evtfoid JOIN pg_namespace n ON n.oid=p.pronamespace ORDER BY 1) q),'fresh_extensions',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT e.extname AS name,e.extversion AS version,n.nspname AS schema,pg_get_userbyid(e.extowner) AS owner FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace ORDER BY 1) q),'fresh_automatic_grant_functions',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT n.nspname AS schema,p.proname AS name,pg_get_function_identity_arguments(p.oid) AS args,CASE WHEN p.prokind IN ('f','p') THEN pg_get_functiondef(p.oid) ELSE '' END AS definition FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.oid IN (SELECT evtfoid FROM pg_event_trigger) AND CASE WHEN p.prokind IN ('f','p') THEN pg_get_functiondef(p.oid) ELSE '' END ~* '(grant|privilege)' ORDER BY 1,2,3) q),'fresh_column_acls',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text COLLATE "C"),'[]'::jsonb) FROM (SELECT n.nspname AS schema,c.relname AS relation,a.attname AS column,a.attacl::text AS acl FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL ORDER BY 1,2,3) q));
actual:=(SELECT jsonb_object_agg(k,encode(sha256(convert_to((SELECT coalesce(jsonb_agg(v ORDER BY v::text COLLATE "C"),'[]'::jsonb) FROM jsonb_array_elements(a) v)::text,'UTF8')),'hex')) FROM jsonb_each(s) e(k,a));
SELECT coalesce(jsonb_agg(v ORDER BY v::text COLLATE "C"),'[]'::jsonb) INTO api FROM jsonb_array_elements(s->'fresh_roles') v WHERE v->>'rolname' IN ('anon','authenticated','service_role');
IF encode(sha256(convert_to(api::text,'UTF8')),'hex') <> 'acc349ef6b809fd72c50354dab8ffde31efdcf35f2a48b550cf4dc8796fe9dc4' THEN RAISE EXCEPTION 'STOP: shared category API role attributes'; END IF;
IF actual->>'columns' <> '1bacc3112e3cb0cdc8cbd1258ee1e584af39a671424ca142d2655cb2477448f0' THEN RAISE EXCEPTION 'STOP: shared category columns'; END IF;
IF actual @> shared_expected AND (actual @> platform_old OR actual @> platform_new) THEN
IF actual @> platform_old THEN matched_family:='cli2.116.0/image17.6.1.165'; ELSE matched_family:='cli2.122.0/image17.11.0.006'; END IF;
RAISE NOTICE 'Recognized exact fresh platform family %',matched_family;
IF EXISTS(SELECT 1 FROM auth.users) OR EXISTS(SELECT 1 FROM public."direct_shift_offers") OR EXISTS(SELECT 1 FROM public."profiles") OR EXISTS(SELECT 1 FROM public."workplaces") OR EXISTS(SELECT 1 FROM public."workplace_members") OR EXISTS(SELECT 1 FROM public."shifts") OR EXISTS(SELECT 1 FROM public."shift_interests") OR EXISTS(SELECT 1 FROM public."coverage_events") OR EXISTS(SELECT 1 FROM public."pilot_audit_events") OR EXISTS(SELECT 1 FROM public."pilot_invitations") OR EXISTS(SELECT 1 FROM public."pilot_audit_aggregates") OR EXISTS(SELECT 1 FROM public."workplace_observers") OR EXISTS(SELECT 1 FROM public."workplace_participant_codes") OR EXISTS(SELECT 1 FROM public."workplace_pilot_settings") OR EXISTS(SELECT 1 FROM public."workplace_shift_codes") THEN RAISE EXCEPTION 'STOP: fresh normalization requires empty disposable baseline'; END IF;
platform_expected:=jsonb_build_object('fresh_schemas',s->'fresh_schemas','fresh_default_acls',s->'fresh_default_acls','fresh_event_triggers',s->'fresh_event_triggers','fresh_automatic_grant_functions',s->'fresh_automatic_grant_functions');
platform_expected:=jsonb_set(platform_expected,'{fresh_default_acls}',(SELECT coalesce(jsonb_agg(v ORDER BY v::text COLLATE "C"),'[]'::jsonb) FROM jsonb_array_elements(platform_expected->'fresh_default_acls') v WHERE NOT(v->>'owner'='postgres' AND v->>'schema'='public' AND v->>'kind' IN ('r','f','S'))));
platform_expected_hashes:=(SELECT jsonb_object_agg(k,encode(sha256(convert_to((SELECT coalesce(jsonb_agg(v ORDER BY v::text COLLATE "C"),'[]'::jsonb) FROM jsonb_array_elements(a) v)::text,'UTF8')),'hex')) FROM jsonb_each(platform_expected) e(k,a));
